-- ─────────────────────────────────────────────────────────────────────────────
-- Contract observability queries across all domains. Not part of the setup: run them in
-- the SQL editor, or build an AI/BI dashboard or SQL alerts on them.
-- Per-domain queries (rule compliance, quarantine) are generated by `contractctl generate`
-- into generated/observability/.
-- ─────────────────────────────────────────────────────────────────────────────
USE CATALOG {{catalog}};

-- 1. Who do I call? Owner and support channels per data product
SELECT r.table_name, r.contract_version, r.status, r.owner_team, s.channel, s.tool, s.url
FROM governance.contract_registry r
LATERAL VIEW explode(r.support) t AS s
WHERE r.is_current
ORDER BY r.table_name;

-- 2. Contract history: every deployed version and the commit it came from
SELECT table_name, contract_version, status, git_commit, published_at, is_current
FROM governance.contract_registry
ORDER BY table_name, published_at DESC;

-- 3. Lineage between data products, as declared in the contracts
SELECT r.table_name AS consumer, i.table_name AS reads_from, i.owner_team AS upstream_owner
FROM governance.contract_registry r
LATERAL VIEW explode(r.inputs) t AS input_id
JOIN governance.contract_registry i ON i.contract_id = input_id AND i.is_current
WHERE r.is_current;

-- 4. SLA and table-level check history
SELECT checked_at, table_name, contract_version, check_name, expected, actual, passed, owner_team, support_channel
FROM governance.contract_sla_results
ORDER BY checked_at DESC;

-- 5. Alert query (Databricks SQL alert: trigger when breaches > 0)
SELECT count(*) AS breaches,
       array_join(collect_set(concat(table_name, ': ', check_name, ' -> ', support_channel)), '; ') AS details
FROM governance.contract_sla_results
WHERE NOT passed AND checked_at >= current_timestamp() - INTERVAL 1 HOUR;
